"""Compile our JSON forest to plain Python branches for lower per-action latency."""
import hashlib
import json
from pathlib import Path


def main():
    raw = Path("assets/equity_model.json").read_bytes()
    m = json.loads(raw)
    def expr(tree, i=0):
        node = tree[i]
        if node[0] < 0:
            return repr(tuple(node[4:]))
        return f"({expr(tree, node[2])} if x[{node[0]}] <= {node[1]} else {expr(tree, node[3])})"
    lines = [
        '"""Generated by tools/export_model.py from our independent offline model."""',
        "MODEL_SHA256 = " + repr(hashlib.sha256(raw).hexdigest()),
        "FEATURE_COUNT = " + str(m["features"]),
    ]
    groups = [m["trees"][i:i + 8] for i in range(0, len(m["trees"]), 8)]
    for i, group in enumerate(groups):
        lines += [f"def _block{i}(x):", "    a = b = c = d = e = f = 0.0"]
        for tree in group:
            lines.append("    n = " + expr(tree))
            for j, var in enumerate("abcdef"):
                lines.append(f"    {var} += n[{j}]")
        lines += ["    return a, b, c, d, e, f", ""]
    lines += ["def predict(x):", "    a, b, c, d, e, f = " + repr(tuple(m["base"]))]
    for i in range(len(groups)):
        lines.append(f"    n = _block{i}(x)")
        for j, var in enumerate("abcdef"):
            lines.append(f"    {var} += n[{j}]")
    lines += ["    return a, b, c, d, e, f", ""]
    Path("bot3/_equity_fast.py").write_text("\n".join(lines), encoding="utf-8")
    print(f"Exported {len(m['trees'])} trees; sha256={hashlib.sha256(raw).hexdigest()}")


if __name__ == "__main__":
    main()
